public sealed class TrimmedEmailComparer : IEqualityComparer<string>
{
    public static readonly TrimmedEmailComparer Instance = new TrimmedEmailComparer();
    public bool Equals(string? x, string? y) =>
        string.Equals(x?.Trim(), y?.Trim(), StringComparison.OrdinalIgnoreCase);
    public int GetHashCode(string obj) =>
        obj.Trim().ToUpperInvariant().GetHashCode();
}

